-- Presentation demo export: 20 synthetic Kalahandi farms and their persisted analysis rows.
-- All parcels are synthetic and non-overlapping; area is 1.6803 acres per farm.
-- Includes rows in public base tables with a farm_id matching these farms, including pipeline and analytics outputs.
-- Does not include farmer credentials/profiles or external lakehouse Parquet/raster files; stored object URIs may require those artifacts.
-- Requires target schema/migrations and the existing farmer_profiles rows listed in the guard below.
BEGIN;
SET LOCAL search_path = public, pg_catalog;
DO $demo_guard$ BEGIN IF (SELECT count(*) FROM public.farmer_profiles WHERE farmer_id = ANY(ARRAY['028878d9-d18c-4418-85a8-8cce3d3d85a9'::uuid, '3f35ca8f-5eb2-4eab-b902-b197dbac391f'::uuid, '8bdfeab0-68f5-4a9d-9563-ec1326628a5d'::uuid, 'f4fd89af-d9b3-4158-b823-45965802cdd6'::uuid]::uuid[])) <> 4 THEN RAISE EXCEPTION 'Required existing farmer_profiles for the four demo farmer IDs are missing'; END IF; END $demo_guard$;
DO $fpo_guard$ BEGIN IF (SELECT count(*) FROM public.fpos WHERE fpo_id = ANY(ARRAY['2ce08e39-d17f-44bb-b3ee-5407d5e28a63'::uuid]::uuid[])) <> 1 THEN RAISE EXCEPTION 'Required existing FPO rows are missing'; END IF; END $fpo_guard$;

